pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz the actor and the provided _unlockTime and an ether amount
    function testFuzz_property(address actor, uint256 providedUnlock, uint256 deposit) public {
        // keep wide but sensible bounds for deposit to avoid overflow and zero-value trivialities
        deposit = bound(deposit, 0, 10 ether);
        vm.deal(actor, deposit);

        // use actor to call Put with providedUnlock and deposit
        vm.prank(actor);
        bool ok;
        // call Put via low-level try/catch to capture any unexpected revert
        try c.Put{value: deposit}(providedUnlock) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property (single assert): if the call succeeded, then the recorded unlockTime for actor
        // must be >= block.timestamp. Reference implementation always enforces this; the mutant that sets
        // acc.unlockTime = providedUnlock can violate it for providedUnlock < block.timestamp.
        if (ok) {
            // read the stored Holder via the autogenerated getter for Acc mapping: Acc(actor) returns (unlockTime, balance)
            (uint256 storedUnlockTime, uint256 storedBalance) = c.Acc(actor);
            assertTrue(storedUnlockTime >= block.timestamp);
        } else {
            // If the Put call reverted, the invariant about post-state does not apply; still assert that call succeeded
            // is not required. To keep a single assertion for the reference holding for all inputs,
            // we consider only successful calls — the reference will succeed for admissible inputs and enforce the invariant.
            // However, assert a trivial true to satisfy single-assert rule when call failed.
            assertTrue(true);
        }
    }
}

