        vm.assume(actor != address(0));
        amount = bound(amount, 0, 10 ether);

        // Fund actor so they can call Put with value `amount`
        vm.deal(actor, amount);

        // Call Put from actor with fuzzed unlock time and amount
        vm.prank(actor);
        c.Put{value: amount}(_unlockTime);

        // Single universal assertion: stored unlockTime for actor is >= current block timestamp
        // This holds for the reference implementation for all inputs, but the mutant that
        // assigns acc.unlockTime = _unlockTime unconditionally will fail for some inputs
