pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed params: actor (caller address) and _unlockTime (time to set), and sent value
    function testFuzz_property(address actor, uint256 _unlockTime, uint256 value) public {
        // keep value in a reasonable range so vm.deal doesn't overflow and not zero to exercise balance change
        value = bound(value, 0, 1 ether);
        // actor must be non-zero
        vm.assume(actor != address(0));

        // record prior stored unlockTime and balance via public getter
        // public mapping Acc returns tuple (unlockTime, balance)
        (uint256 priorUnlock, uint256 priorBalance) = c.Acc(actor);

        // fund actor and perform Put from actor
        vm.deal(actor, value);
        vm.prank(actor);
        // perform call; catch revert not expected here but follow rules: use try/catch to observe success
        bool ok;
        try c.Put{value: value}(_unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful Put on the reference contract, balance must have increased by value
        // For the general rule we assert that if the call succeeded then Acc[actor].balance == priorBalance + value
        // This property holds for the reference and is violated by mutants that might manipulate balances incorrectly.
        (uint256 newUnlock, uint256 newBalance) = c.Acc(actor);

        // Single assertion as required: assertTrue over a getter-based fact.
        // If the call reverted, then ok==false and we assert that (ok == false) implies newBalance == priorBalance (no change)
        // But to keep a single assertTrue reading c only, we assert the following condition via the public getter:
        // either the call failed (ok == false) and balance unchanged, OR call succeeded and balance increased by value.
        // We express this as a boolean using only c's getters and local ok.
        bool prop;
        if (!ok) {
            // call reverted: balance should remain unchanged
            prop = (newBalance == priorBalance);
        } else {
            prop = (newBalance == priorBalance + value);
        }

        assertTrue(prop);
    }
}

