pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz params: caller address, deposit amount, and candidate unlock time to set
    function testFuzz_property(address caller, uint256 deposit, uint256 candidateUnlock) public {
        // Keep caller non-zero and deposit reasonably bounded but wide
        vm.assume(caller != address(0));
        deposit = bound(deposit, 0, 5 ether);

        // Ensure caller has funds to send
        vm.deal(caller, deposit + 1 ether);

        // 1) First, have caller call Put with some initial unlock time to set a baseline
        uint256 initialUnlock = block.timestamp + 1 days;
        vm.prank(caller);
        if (deposit > 0) {
            c.Put{value: deposit}(initialUnlock);
        } else {
            // allow zero deposit as well
            c.Put{value: 0}(initialUnlock);
        }

        // Read the stored unlockTime after first Put
        uint256 before = c.Acc(caller).unlockTime;

        // 2) Now call Put again with fuzzed candidateUnlock (this is where mutant differs)
        // give caller some more funds so the call can send deposit as well
        vm.deal(caller, deposit + 1 ether);
        vm.prank(caller);
        if (deposit > 0) {
            c.Put{value: deposit}(candidateUnlock);
        } else {
            c.Put{value: 0}(candidateUnlock);
        }

        // Read the stored unlockTime after second Put
        uint256 after = c.Acc(caller).unlockTime;

        // The reference implementation never decreases a holder's unlockTime via Put
        // (it stores max(_unlockTime, block.timestamp) so second Put cannot set unlockTime < before)
        // The mutant that assigns candidateUnlock unconditionally can make `after < before` for some inputs.
        assertTrue(after >= before);
    }
}

