pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzzed params: actor (sender), amount to deposit, desired unlock time
    function testFuzz_property(address actor, uint256 amount, uint256 desiredUnlock) public {
        // admissible domain: amount must be > 0 and at least MinSum so Collect logic in original uses MinSum,
        // but here we only need to make a nonzero payable deposit. Keep domain wide but require amount > 0.
        vm.assume(actor != address(0));
        vm.assume(amount > 0);

        // ensure actor has ETH to send
        vm.deal(actor, amount);

        // perform the Put from actor with provided desiredUnlock
        vm.prank(actor);
        c.Put{value: amount}(desiredUnlock);

        // The universal property: in reference C, stored unlockTime is never less than the provided desiredUnlock
        // (it sets acc.unlockTime = _unlockTime>block.timestamp?_unlockTime:block.timestamp;)
        // We read the public mapping getter Acc(actor).unlockTime via the autogenerated getter.

        (uint unlockTime, ) = c.Acc(actor);

        // single assertion: the reference ensures unlockTime >= desiredUnlock OR unlockTime >= block.timestamp
        // But since this test runs immediately after the call, block.timestamp is the same as inside Put or greater;
        // however the key general rule we assert is unlockTime >= desiredUnlock || unlockTime >= block.timestamp
        // This is equivalent to unlockTime >= min(desiredUnlock, block.timestamp).
        // The mutant that unconditionally sets unlockTime = block.timestamp can violate unlockTime >= desiredUnlock
        // when desiredUnlock > block.timestamp. Our assertion encodes the reference's rule so it should hold for all inputs.

        // We must read block.timestamp here; it's the current test timestamp which is >= the timestamp inside Put.
        uint nowTs = block.timestamp;

        // The property: unlockTime >= desiredUnlock OR unlockTime >= nowTs
        // If desiredUnlock <= nowTs, the condition reduces to unlockTime >= nowTs which is the same as reference behavior.
        // If desiredUnlock > nowTs, reference sets unlockTime = desiredUnlock (since desiredUnlock>block.timestamp),
        // so unlockTime >= desiredUnlock holds. The mutant that sets unlockTime = block.timestamp will fail when
        // desiredUnlock > nowTs because unlockTime == nowTs < desiredUnlock.

        assertTrue(unlockTime >= desiredUnlock || unlockTime >= nowTs);
    }
}

