    function testFuzz_property(address actor, uint256 initialFuture, uint256 laterProvided, uint256 amount) public {
        // Keep actor non-zero and amount > 0 (Put needs to deposit to affect unlockTime)
        vm.assume(actor != address(0));
        // bound amount to a reasonable gas-affordable range and nonzero
