        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(initialFuture);

        // Record the stored unlockTime after the first deposit
        uint256 storedAfterFirst = c.Acc(actor).unlockTime;

        // The reference contract guarantees the stored unlockTime is at least block.timestamp and at least the lesser of initialFuture and block.timestamp.
        // We focus on the preservation property: after setting a future unlockTime, a subsequent Put with a smaller provided unlock should NOT decrease the stored unlockTime below the previously stored value.
        // 2) Second deposit by same actor with possibly different provided unlock time (laterProvided) and some (possibly zero) additional amount
        uint256 addAmount = bound(amount, 0 wei, 10 ether);
        // ensure actor has funds for second deposit
