    function testFuzz_property(address actor, uint256 initialFuture, uint256 laterOffset, uint256 deposit1, uint256 deposit2) public {
        // keep values in sensible wide ranges
        vm.assume(actor != address(0));
        // initialFuture should be at least 1 second ahead to be a future time
        initialFuture = bound(initialFuture, 1, 10 days);
        // laterOffset is how much we advance time before second deposit: allow 0..10 days
        laterOffset = bound(laterOffset, 0, 10 days);
        // small positive deposits (allow zero for coverage, but Put with 0 still updates unlockTime in reference)
        deposit1 = bound(deposit1, 1 wei, 10 ether);
        deposit2 = bound(deposit2, 0 wei, 10 ether);

        // Step 1: Actor makes an initial Put setting a future unlockTime = block.timestamp + initialFuture
        vm.deal(actor, deposit1 + deposit2 + 1 ether);
        uint256 futureTime = block.timestamp + initialFuture;
        vm.prank(actor);
        c.Put{value: deposit1}(futureTime);

        // read stored unlockTime after first Put
        (uint256 storedUnlock1, ) = getAcc(actor);
        // it must be at least the reported futureTime (reference ensures choosing _unlockTime>block.timestamp? _unlockTime : block.timestamp)
        // because we set _unlockTime > block.timestamp, storedUnlock1 >= futureTime
        // enforce with assumption to avoid degenerate paths: require storedUnlock1 >= futureTime
        vm.assume(storedUnlock1 >= futureTime);

        // Step 2: advance time by laterOffset, then call Put again with a small _unlockTime (0) and deposit2 value
        vm.warp(block.timestamp + laterOffset);
        vm.prank(actor);
        c.Put{value: deposit2}(0);

        // After the second Put, the reference contract preserves the previously larger unlockTime (it remains >= storedUnlock1)
        (uint256 storedUnlock2, ) = getAcc(actor);

        // The property: storedUnlock2 >= storedUnlock1
        // This holds for the reference implementation for all inputs; the mutant that sets unlockTime = block.timestamp can make storedUnlock2 < storedUnlock1 for some inputs
        assertTrue(storedUnlock2 >= storedUnlock1);
    }

    // helper to call the public getter Acc(address) which returns (uint,uint) via generated getter
    function getAcc(address a) internal returns (uint256 unlockTime, uint256 balance) {
        // The autogenerated getter for public mapping Acc returns the Holder struct as a tuple
        (uint256 u, uint256 b) = c.Acc(a);
        return (u, b);
    }
}

